import React from 'react';
import styled from 'styled-components';
import katowice from '../../images/katowice.jpg';


const Slideshow = () => {


    return (
        <SlideContainer>
            <div className="each-slide">
                <div style={{
                    'backgroundImage': `url(${katowice})`,
                    'height': '450px',
                    'width': '1440px',
                    'backgroundPosition': 'center',
                    'backgroundSize': 'cover',
                }}>
                    <TextBox>
                        <TitleSlide>Profesjonalne usługi księgowe</TitleSlide>
                        <SubtitleSlide>Lorem ipsum</SubtitleSlide>
                    </TextBox>

                </div>
            </div>
        </SlideContainer>
    )
}

export default Slideshow

const SlideContainer = styled.div`
    margin: 8.5rem auto;
    height: 40%;
    width: 100%;
`;

const TextBox = styled.div`
    position: absolute;
    margin-top: 10rem;
    margin-left: 10rem;
`;

const TitleSlide = styled.h1`
    text-align: left;
    color: white;
`;

const SubtitleSlide = styled.p`
    text-align: left;
    color: white;
`;
